// src/screens/HomeScreen.js - главный экран приложения
import React from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  StyleSheet, 
  // Убраны неиспользуемые ScrollView, ActivityIndicator, Alert, Image
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';


const HomeScreen = ({ navigation }) => {

  // --- Компонент навигационной кнопки ---
  const NavigationButton = ({ screen, title, icon, color }) => (
    <TouchableOpacity
      style={[styles.navButton, { backgroundColor: color }]}
      onPress={() => navigation.navigate(screen)}
    >
      <Ionicons name={icon} size={30} color="white" style={{ marginBottom: 8 }} />
      <Text style={styles.navButtonText}>{title}</Text>
    </TouchableOpacity>
  );

  return (
    <View style={styles.container}> 

      {/* УДАЛЕНО: Секция header с подзаголовком "Выберите раздел для продолжения работы." */}
      <View style={styles.header}>
        <Text style={styles.mainTitle}>Главная Панель</Text>
        {/* УДАЛЕНО: <Text style={styles.subtitle}>Выберите раздел для продолжения работы.</Text> */}
      </View>

      {/* Секция Навигация */}
      <View style={styles.navigationSection}>

        <View style={styles.navRow}>
          <NavigationButton 
            screen="Media" 
            title="Мультимедиа" 
            icon="camera-outline" 
            color="#34C759" 
          />
          <NavigationButton 
            screen="Gallery" 
            title="Галерея" 
            icon="images-outline" 
            color="#FF9500" 
          />
        </View>

        <View style={styles.navRow}>
          <NavigationButton 
            screen="Analytics" 
            title="Аналитика" 
            icon="stats-chart-outline" 
            color="#5856D6" 
          />
          <NavigationButton 
            screen="Settings" 
            title="Настройки" 
            icon="settings-outline" 
            color="#FF3B30" 
          />
        </View>
      </View>

    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f0ffef', 
    padding: 20,
    justifyContent: 'center', 
  },
  header: {
    marginBottom: 40,
    alignItems: 'center',
  },
  mainTitle: {
    fontSize: 32,
    fontWeight: '700',
    color: '#1c1c1e',
    // marginBottom: 5, // Убран лишний отступ, так как нет подзаголовка
    marginBottom: 0,
  },
  subtitle: { // Стиль сохранен, но не используется
    fontSize: 16,
    color: '#6c757d',
  },
  navigationSection: {
    backgroundColor: 'white',
    padding: 20,
    borderRadius: 15,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.1,
    shadowRadius: 10,
    elevation: 5,
  },
  navRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 15,
  },
  navButton: {
    paddingHorizontal: 15,
    paddingVertical: 25, 
    borderRadius: 12,
    alignItems: 'center',
    flex: 1,
    marginHorizontal: 8,
    minHeight: 120, 
    justifyContent: 'center',
  },
  navButtonText: {
    color: 'white',
    fontSize: 15,
    fontWeight: '700',
    textAlign: 'center',
  },
});

export default HomeScreen;
